; =============================================================================
; naka_ui_macros.s -- the HD-AE5000 GUI, written as a tree of NAKA objects
; =============================================================================
; GENERATED by scripts/converters/hdae5000_ui_tree.py --macros (one macro per NAKA
; class the HD-AE5000 instantiates, from the class definitions the firmware itself
; carries: propdata / propname of the main CPU's class tables and of
; HDAE5000_RECORD_TABLE).  The tree macros below are hand-written and kept by the
; generator verbatim.  Shared by hdae5000/ (v2.06i) and hdae5000_v2_01i/ (v2.01i).
;
; HOW A TREE IS WRITTEN (hdae5000_ui_tree.s):
;     TtlScreenR      HDDMENU, x=0, y=0, w=320, h=240, title="HD-AE5000", ...
;     ui_sub
;             AcScreenMenu    HDDMENU_SETUP_TOOLS, ..., screen=HDAE5000_OBJ_SETUPS_TOOLS
;     ui_endsub
; Every object is one class-macro line; `ui_sub` / `ui_endsub` bracket its children.
; The macros number the objects in the order they appear (the object table is the
; preorder walk of the tree) and compute each record's four Viewable links from the
; nesting: super = the enclosing object, sub = its first child, next / prev = the
; neighbours inside the same ui_sub (NAKA_NONE where there is none; top-level
; objects are not linked to each other).  They also define, per object NAME:
;     HDAE5000_OBJ_NAME   its object id, 0x007F0000 + index (table 0x7F)
;     HdaeUi_NAME         its record in the ROM pool (HdaeUiRam_NAME in the .data image)
;     HdaeUi_NAME_<field> its inline caption, for a string field given as "text"
;     HdaeUiName_NAME     its name string (ui_name / ui_noname, in the name pool)
; Parameters are the firmware's field names.  Geometry is x, y, w, h: the record stores
; Viewable.rect as x1, y1, x2, y2 inclusive (x2 = x + w - 1); record 0 is 0,0-319,239,
; the 320 x 240 screen.  A string field is either fld="text" (an inline caption,
; stored after the record) or fld_at=Label (a pointer to a string elsewhere, 0 = none).
; A RAM-variable field (types m n r s) takes the label of the variable's initial value
; in the .data image (HdaeUiVar_*); the record holds its RAM address.  Defaults are the
; value most records of the class share; an object that differs says so.
; =============================================================================

	.equ	NAKA_NONE, 0xffff		; no object (a Viewable link)
	.equ	NAKA_NO_OBJECT, 0xffffffff	; no object (a 32-bit object id field)
; LCD edit switches, the values of every `editsw` field (main CPU numbering: GetEditSwPoint /
; SeTitle_DecodeSwitch, technics-docs ui-framework.md): COL1-8 the eight buttons under the
; display, RIGHT1-5 / LEFT1-5 the side rows top to bottom (LEFT = RIGHT | 0x80).  Every
; HD-AE5000 object with one sits next to it (notes/data-gui-hdae5000-2026-10-29/probes/
; editsw_geometry.py).
	.equ	EDITSW_COL1, 0x00
	.equ	EDITSW_COL2, 0x01
	.equ	EDITSW_COL3, 0x02
	.equ	EDITSW_COL4, 0x03
	.equ	EDITSW_COL5, 0x04
	.equ	EDITSW_COL6, 0x05
	.equ	EDITSW_COL7, 0x06
	.equ	EDITSW_COL8, 0x07
	.equ	EDITSW_RIGHT1, 0x08
	.equ	EDITSW_RIGHT2, 0x09
	.equ	EDITSW_RIGHT3, 0x0a
	.equ	EDITSW_RIGHT4, 0x0b
	.equ	EDITSW_RIGHT5, 0x0c
	.equ	EDITSW_LEFT1, 0x88
	.equ	EDITSW_LEFT2, 0x89
	.equ	EDITSW_LEFT3, 0x8a
	.equ	EDITSW_LEFT4, 0x8b
	.equ	EDITSW_LEFT5, 0x8c
	.equ	EDITSW_NONE, 0xff

