;   chain: Viewable
;   fields after Viewable's class / super / sub / next / prev / flag / rect (+0..+21):
;     (none)
	.macro	Viewable obj, x, y, w, h, flag
	_ui_head	\obj, Viewable, \flag, \x, \y, \w, \h
	.endm

